const cache = {}
export function getDefaultPriceList(slug) {
  const key = PRICES[slug] ? slug : 'buco'
  if (cache[key]) return cache[key]
  const prices = PRICES[key]
  const verified = VERIFIED[key] || {}
  const categories = CATEGORY_NAMES.map((category) => ({ category, items: [] }))
  const items = []
  MASTER.forEach(([code, cat, description, unit]) => {
    const price = prices[code]
    const v = verified[code]
    const item = {
      code,
      description,
      quantity: null,
      unit,
      price,
      priceInclVat: Math.round(price * 1.15 * 100) / 100,
      verified: !!v,
      brand: v ? v[0] : '',
      spec: v ? v[1] : ''
    }
    categories[cat].items.push(item)
    items.push({ ...item, category: CATEGORY_NAMES[cat] })
  })
  const record = {
    supplier: 'Built-in demo price list',
    fileName: 'GnA Fast Quote price list (built in)',
    uploadedAt: '2026-10-15T00:00:00.000Z',
    uploadedBy: 'built-in demo data',
    categories,
    items,
    totalItems: items.length,
    verifiedItems: Object.keys(verified).length,
    isBuiltIn: true
  }
  cache[key] = record
  return record
}
